class Solution {
  public long numberOfRightTriangles(int[][] grid) {
    int n = grid.length, m = grid[0].length;
    int[][] row = new int[n][m], col = new int[n][m];
    for (int i = 0; i < n; i++) {
      int count = 0;
      for (int j = 0; j < m; j++) {
        row[i][j] = count;
        count += grid[i][j];
      }
    }
    for (int j = 0; j < m; j++) {
      int count = 0;
      for (int i = 0; i < n; i++) {
        col[i][j] = count;
        count += grid[i][j];
      }
    }
    long ans = 0;
    for (int i = 0; i < n; i++)
      for (int j = 0; j < m; j++)
        if (grid[i][j] == 1) {
          int left = row[i][j], up = col[i][j];
          int right = row[i][m - 1] + grid[i][m - 1] - row[i][j] - 1;
          int down = col[n - 1][j] + grid[n - 1][j] - col[i][j] - 1;
          ans += (long) left * down + (long) right * down + (long) left * up + (long) right * up;
        }
    return ans;
  }
}
